use cq_lang_datalog_storage::incremental::strata::source;
fn main() {
 let text = std::fs::read_to_string(std::env::args().nth(1).unwrap()).unwrap();
 let text = &text[text.find("        struct Doop;").unwrap()..text.find("        };\n").unwrap()];
 let p: source::Program = syn::parse_str(text).unwrap();
 let s = cq_datalog_stratify::compile(&p).unwrap();
 let i = cq_datalog_incremental::compile_with_advice(&s, cq_datalog_incremental::DriverPolicy::DeltaFirst, &[]).unwrap();
 let t = cq_datalog_storage::compile(&i).unwrap();
 for (id,d) in p.declarations.iter().enumerate() { println!("REL\t{}\t{}\t{}\t{}",d.name,d.arity(),d.value.is_some(),t.providers[id].canonical); }
 for (id,l) in t.layouts.iter().enumerate() {println!("FULL\t{}\t{}\t{:?}\t{}",id,l.relation,l.columns,l.key);}
 for (id,l) in t.delta_layouts.iter().enumerate() {println!("DELTA\t{}\t{}\t{:?}\t{}",id,l.relation,l.columns,l.key);}
 for (id,n) in t.negations.iter().enumerate() {println!("NEG\t{}\t{}\t{:?}",id,p.declarations[n.relation].name,n.columns);}
}

